package com.smartjobtracker.controller;
import com.smartjobtracker.model.*; import com.smartjobtracker.repository.UserRepository; import com.smartjobtracker.service.GmailService; import org.springframework.beans.factory.annotation.Value; import org.springframework.http.ResponseEntity; import org.springframework.security.core.Authentication; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.web.bind.annotation.*; import org.springframework.web.servlet.view.RedirectView; import java.util.List; import java.util.Map;
@RestController @RequestMapping("/api/gmail") public class GmailController { private final GmailService service; private final UserRepository users; private final String frontendUrl; public GmailController(GmailService service,UserRepository users,@Value("${app.frontend-url:http://localhost:5173}")String frontendUrl){this.service=service;this.users=users;this.frontendUrl=frontendUrl;} @GetMapping("/connect") public ResponseEntity<Map<String,String>> connect(){return ResponseEntity.ok(Map.of("authorizationUrl",service.begin(userId())));} @GetMapping("/callback") public RedirectView callback(@RequestParam String state,@RequestParam(required=false) String code,@RequestParam(required=false) String error){try{if(error!=null&&!error.isBlank())throw new IllegalArgumentException("Gmail authorization denied");service.callback(state,code);return new RedirectView(frontendUrl+"/profile?gmail=connected");}catch(RuntimeException ex){return new RedirectView(frontendUrl+"/profile?gmail=error");}} @GetMapping("/status") public Map<String,Object> status(){return service.status(userId());} @PostMapping("/sync") public Map<String,Integer> sync(){return Map.of("processed",service.sync(userId()));} @GetMapping("/review") public List<IngestedEmail> review(){return service.reviewQueue(userId());} @PostMapping("/review/{emailId}") public ResponseEntity<Void> review(@PathVariable Long emailId,@RequestBody ReviewRequest request){service.review(userId(),emailId,request.applicationId(),request.status());return ResponseEntity.noContent().build();} @DeleteMapping public ResponseEntity<Void> disconnect(){service.disconnect(userId());return ResponseEntity.noContent().build();} private Long userId(){Authentication a=SecurityContextHolder.getContext().getAuthentication();return users.findByEmail(a.getName()).map(User::getId).orElseThrow(()->new IllegalStateException("User not found"));} public record ReviewRequest(Long applicationId,ApplicationStatus status){} }